async function getDashboardData() {
  try {
    // Using a base URL for server-side fetching. 
    // In a real app, this would be an environment variable.
    const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3000';

    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then(res => {
        if (!res.ok) throw new Error('Failed to fetch analytics');
        return res.json();
      }),
      fetch(`${baseUrl}/api/notifications`).then(res => {
        if (!res.ok) throw new Error('Failed to fetch notifications');
        return res.json();
      }),
      fetch(`${baseUrl}/api/settings`).then(res => {
        if (!res.ok) throw new Error('Failed to fetch settings');
        return res.json();
      })
    ]);

    return { analytics, notifications, settings };
  } catch (error) {
    console.error('Error fetching dashboard data:', error);
    // Return mock data as fallback, following the pattern in page.tsx
    return {
      analytics: { 
        views: 1250, 
        uniqueVisitors: 850, 
        bounceRate: '42%' 
      },
      notifications: [
        { id: 1, message: 'New user signed up', time: '2 mins ago' },
        { id: 2, message: 'System maintenance scheduled', time: '1 hour ago' },
        { id: 3, message: 'Backup completed successfully', time: '3 hours ago' }
      ],
      settings: { 
        theme: 'light', 
        emailNotifications: true,
        dashboardLayout: 'compact'
      }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div className="p-4 space-y-6">
      <h2 className="text-2xl font-bold">Dashboard Overview</h2>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* Analytics Section */}
        <div className="p-4 border rounded-lg shadow-sm bg-white">
          <h3 className="text-lg font-semibold mb-2">Analytics</h3>
          <div className="space-y-2">
            <div className="flex justify-between">
              <span>Views:</span>
              <span className="font-medium">{analytics.views}</span>
            </div>
            <div className="flex justify-between">
              <span>Unique Visitors:</span>
              <span className="font-medium">{analytics.uniqueVisitors}</span>
            </div>
            <div className="flex justify-between">
              <span>Bounce Rate:</span>
              <span className="font-medium">{analytics.bounceRate}</span>
            </div>
          </div>
        </div>

        {/* Notifications Section */}
        <div className="p-4 border rounded-lg shadow-sm bg-white">
          <h3 className="text-lg font-semibold mb-2">Notifications</h3>
          <ul className="space-y-2">
            {notifications.map((notification: any) => (
              <li key={notification.id} className="text-sm border-b pb-1 last:border-0">
                <p>{notification.message}</p>
                <span className="text-xs text-gray-500">{notification.time}</span>
              </li>
            ))}
          </ul>
        </div>

        {/* Settings Section */}
        <div className="p-4 border rounded-lg shadow-sm bg-white">
          <h3 className="text-lg font-semibold mb-2">Settings Status</h3>
          <div className="space-y-2">
             <div className="flex justify-between">
              <span>Theme:</span>
              <span className="capitalize">{settings.theme}</span>
            </div>
            <div className="flex justify-between">
              <span>Email Alerts:</span>
              <span>{settings.emailNotifications ? 'On' : 'Off'}</span>
            </div>
             <div className="flex justify-between">
              <span>Layout:</span>
              <span className="capitalize">{settings.dashboardLayout}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

