2.  **Error Handling**: Catches fetch errors and returns structured mock data as a fallback, ensuring the UI always renders (similar to the pattern in `app/page.tsx`).
3.  **Type Safety**: Defined TypeScript interfaces (`AnalyticsData`, `Notification`, `SettingsData`, `DashboardData`) for robust type checking.
4.  **Styling**: Added inline styles to ensure the dashboard looks presentable without relying on external CSS frameworks like Tailwind (which wasn't configured).

You can review the changes in `app/Dashboard.tsx`.

```typescript
interface AnalyticsData {
  views: number;
  uniqueVisitors: number;
  bounceRate: string;
}

interface Notification {
  id: number;
  message: string;
  time: string;
}

interface SettingsData {
  theme: string;
  emailNotifications: boolean;
  dashboardLayout: string;
}

interface DashboardData {
  analytics: AnalyticsData;
  notifications: Notification[];
  settings: SettingsData;
}

async function getDashboardData(): Promise<DashboardData> {
  try {
    // Using a base URL for server-side fetching. 
    // In a real app, this would be an environment variable.
    const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3000';

    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then(res => {
        if (!res.ok) throw new Error('Failed to fetch analytics');
        return res.json();
      }),
      fetch(`${baseUrl}/api/notifications`).then(res => {
        if (!res.ok) throw new Error('Failed to fetch notifications');
        return res.json();
      }),
      fetch(`${baseUrl}/api/settings`).then(res => {
        if (!res.ok) throw new Error('Failed to fetch settings');
        return res.json();
      })
    ]);

    return { analytics, notifications, settings };
  } catch (error) {
    console.error('Error fetching dashboard data:', error);
    // Return mock data as fallback, following the pattern in page.tsx
    return {
      analytics: { 
        views: 1250, 
        uniqueVisitors: 850, 
        bounceRate: '42%' 
      },
      notifications: [
        { id: 1, message: 'New user signed up', time: '2 mins ago' },
        { id: 2, message: 'System maintenance scheduled', time: '1 hour ago' },
        { id: 3, message: 'Backup completed successfully', time: '3 hours ago' }
      ],
      settings: { 
        theme: 'light', 
        emailNotifications: true,
        dashboardLayout: 'compact'
      }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div style={{ padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h2 style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '20px' }}>Dashboard Overview</h2>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px' }}>
        {/* Analytics Section */}
        <div style={{ padding: '15px', border: '1px solid #e5e7eb', borderRadius: '8px', boxShadow: '0 1px 2px rgba(0,0,0,0.05)' }}>
          <h3 style={{ fontSize: '18px', fontWeight: '600', marginBottom: '10px' }}>Analytics</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Views:</span>
              <span style={{ fontWeight: '500' }}>{analytics.views}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Unique Visitors:</span>
              <span style={{ fontWeight: '500' }}>{analytics.uniqueVisitors}</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Bounce Rate:</span>
              <span style={{ fontWeight: '500' }}>{analytics.bounceRate}</span>
            </div>
          </div>
        </div>

        {/* Notifications Section */}
        <div style={{ padding: '15px', border: '1px solid #e5e7eb', borderRadius: '8px', boxShadow: '0 1px 2px rgba(0,0,0,0.05)' }}>
          <h3 style={{ fontSize: '18px', fontWeight: '600', marginBottom: '10px' }}>Notifications</h3>
          <ul style={{ listStyle: 'none', padding: 0, margin: 0, display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {notifications.map((notification) => (
              <li key={notification.id} style={{ paddingBottom: '8px', borderBottom: '1px solid #f3f4f6' }}>
                <p style={{ margin: 0 }}>{notification.message}</p>
