            </div>
             <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>Layout:</span>
              <span style={{ textTransform: 'capitalize' }}>{settings.dashboardLayout}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
